		return "Activated"
	case memoryloop.LifecycleActionPromote:
		return "Promoted"
	case memoryloop.LifecycleActionSuppress:
		return "Suppressed"
	case memoryloop.LifecycleActionUnsuppress:
		return "Unsuppressed"
	case memoryloop.LifecycleActionArchive:
		return "Archived"
	default:
		return "Updated"
	}
}

