	}
	if snapshot.Scope != "" {
		fmt.Fprintf(w, "Scope: %s", snapshot.Scope)
		if snapshot.ScopeValue != "" {
			fmt.Fprintf(w, " (%s)", snapshot.ScopeValue)
		}
