func frequentMemoryTitles(snapshot *memoryloop.Snapshot, logs []memoryloop.InjectionLog) []string {
	if snapshot == nil {
		return nil
	}
	titleByID := make(map[string]string, len(snapshot.Records))
	for _, record := range snapshot.Records {
		titleByID[record.ID] = record.Title
	}
	counts := make(map[string]int)
	for _, log := range logs {
		for _, id := range log.InjectedMemoryIDs {
			counts[id]++
		}
	}

	type pair struct {
		title string
		count int
	}
	pairs := make([]pair, 0, len(counts))
	for id, count := range counts {
		pairs = append(pairs, pair{title: titleByID[id], count: count})
	}
	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].count != pairs[j].count {
			return pairs[i].count > pairs[j].count
		}
		return pairs[i].title < pairs[j].title
	})

	out := make([]string, 0, len(pairs))
	for _, item := range pairs {
		if item.title == "" {
			continue
		}
		out = append(out, fmt.Sprintf("%s (%d)", item.title, item.count))
	}
	return out
}

func indentBlock(text, indent string) string {
	lines := strings.Split(strings.TrimSpace(text), "\n")
	for i, line := range lines {
		lines[i] = indent + line
	}
	return strings.Join(lines, "\n")
}

func formatOptionalScopeValue(value string) string {
	if strings.TrimSpace(value) == "" {
		return ""
	}
	return fmt.Sprintf(" (%s)", strings.TrimSpace(value))
}

func formatMemoryLoopRecordScope(record memoryloop.MemoryRecord) string {
	scope := string(record.ScopeKind)
	if scope == "" {
		scope = string(memoryloop.ScopeKindMe)
	}
	if strings.TrimSpace(record.ScopeValue) == "" {
		return scope
	}
	return fmt.Sprintf("%s(%s)", scope, strings.TrimSpace(record.ScopeValue))
}

func resolveMemoryLoopScope(ctx context.Context, scopeArg, branchArg string) (memoryLoopScope, error) {
	scope := memoryLoopScope{Mode: memoryLoopScopeMode(strings.ToLower(strings.TrimSpace(scopeArg)))}
	if scope.Mode == "" {
		scope.Mode = memoryLoopScopeRepo
	}

	switch scope.Mode {
	case memoryLoopScopeRepo:
		repo, err := openRepository(ctx)
		if err != nil {
			return memoryLoopScope{}, fmt.Errorf("open git repository: %w", err)
		}
		defaultBranch, _, err := resolveMemoryLoopDefaultBranch(repo)
		if err != nil {
			return memoryLoopScope{}, err
		}
		scope.Branch = defaultBranch
		return scope, nil
	case memoryLoopScopeBranch:
		if branch := strings.TrimSpace(branchArg); branch != "" {
			scope.Branch = branch
			return scope, nil
		}
		repo, err := openRepository(ctx)
		if err != nil {
			return memoryLoopScope{}, fmt.Errorf("open git repository: %w", err)
		}
		branch := strategy.GetCurrentBranchName(repo)
		if branch == "" {
			return memoryLoopScope{}, errors.New("current HEAD is detached; pass --branch when using --scope branch")
		}
		scope.Branch = branch
		return scope, nil
	case memoryLoopScopeMe:
		ownerID, err := configuredMemoryLoopOwnerID(ctx)
		if err != nil {
			return memoryLoopScope{}, err
		}
		scope.OwnerID = ownerID
		return scope, nil
	default:
		return memoryLoopScope{}, fmt.Errorf("invalid scope %q: must be repo, branch, or me", scopeArg)
	}
}

func queryMemoryLoopRows(ctx context.Context, idb *insightsdb.InsightsDB, scope memoryLoopScope, last int) ([]insightsdb.SessionRow, error) {
	switch scope.Mode {
	case memoryLoopScopeRepo:
		repo, err := openRepository(ctx)
		if err != nil {
			return nil, fmt.Errorf("query repo-scoped sessions: open git repository: %w", err)
		}
		_, defaultBranchHash, err := resolveMemoryLoopDefaultBranch(repo)
		if err != nil {
			return nil, fmt.Errorf("query repo-scoped sessions: %w", err)
		}
		reachableCheckpointIDs, err := listReachableCheckpointIDs(ctx, repo, defaultBranchHash)
		if err != nil {
			return nil, fmt.Errorf("query repo-scoped sessions: %w", err)
		}
		totalSessions, err := idb.SessionCount(ctx)
		if err != nil {
			return nil, fmt.Errorf("query repo-scoped sessions: %w", err)
		}
		rows, err := idb.QueryLastNSessions(ctx, totalSessions)
		if err != nil {
			return nil, fmt.Errorf("query repo-scoped sessions: %w", err)
		}
		filtered := make([]insightsdb.SessionRow, 0, len(rows))
		for _, row := range rows {
			if _, ok := reachableCheckpointIDs[row.CheckpointID]; !ok {
				continue
			}
			filtered = append(filtered, row)
			if last > 0 && len(filtered) >= last {
				break
			}
		}
		return filtered, nil
	case memoryLoopScopeBranch:
		rows, err := idb.QueryByBranch(ctx, scope.Branch, last)
		if err != nil {
			return nil, fmt.Errorf("query branch-scoped sessions: %w", err)
		}
		return rows, nil
	case memoryLoopScopeMe:
		rows, err := idb.QueryByOwnerID(ctx, scope.OwnerID, last)
		if err != nil {
			return nil, fmt.Errorf("query owner-scoped sessions: %w", err)
		}
		return rows, nil
	default:
		return nil, fmt.Errorf("unsupported scope mode %q", scope.Mode)
	}
}

func resolveMemoryLoopDefaultBranch(repo *git.Repository) (string, plumbing.Hash, error) {
	defaultBranch := strings.TrimSpace(strategy.GetDefaultBranchName(repo))
	if defaultBranch == "" {
		return "", plumbing.ZeroHash, errors.New("could not determine default branch for --scope repo")
	}

	ref, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
	if err != nil {
		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", defaultBranch), true)
	}
	if err != nil {
		return "", plumbing.ZeroHash, fmt.Errorf("resolve default branch %q: %w", defaultBranch, err)
	}

	return defaultBranch, ref.Hash(), nil
}

func listReachableCheckpointIDs(ctx context.Context, repo *git.Repository, from plumbing.Hash) (map[string]struct{}, error) {
	if from == plumbing.ZeroHash {
		return nil, errors.New("default branch has no commits")
	}

	iter, err := repo.Log(&git.LogOptions{
		From:  from,
		Order: git.LogOrderCommitterTime,
	})
	if err != nil {
		return nil, fmt.Errorf("iterate default branch history: %w", err)
	}
	defer iter.Close()

	checkpointIDs := make(map[string]struct{})
	err = iter.ForEach(func(commit *object.Commit) error {
		if err := ctx.Err(); err != nil {
			return err //nolint:wrapcheck // Propagating context cancellation
		}
		for _, checkpointID := range trailers.ParseAllCheckpoints(commit.Message) {
			checkpointIDs[checkpointID.String()] = struct{}{}
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("scan default branch history: %w", err)
	}

	return checkpointIDs, nil
}

func filterMemoryLoopRows(rows []insightsdb.SessionRow, scope memoryLoopScope, limit int) ([]insightsdb.SessionRow, error) {
	filtered := make([]insightsdb.SessionRow, 0, len(rows))
	for _, row := range rows {
		switch scope.Mode {
		case memoryLoopScopeRepo:
			filtered = append(filtered, row)
		case memoryLoopScopeBranch:
			if row.Branch == scope.Branch {
				filtered = append(filtered, row)
			}
		case memoryLoopScopeMe:
			if strings.EqualFold(row.OwnerID, scope.OwnerID) {
				filtered = append(filtered, row)
			}
		default:
			return nil, fmt.Errorf("unsupported scope mode %q", scope.Mode)
		}
	}

	sort.SliceStable(filtered, func(i, j int) bool {
		return filtered[i].CreatedAt.After(filtered[j].CreatedAt)
	})
	if limit > 0 && len(filtered) > limit {
		filtered = filtered[:limit]
	}
	return filtered, nil
}

func scopeValue(scope memoryLoopScope) string {
	switch scope.Mode {
	case memoryLoopScopeRepo:
		return ""
	case memoryLoopScopeBranch:
		return scope.Branch
	case memoryLoopScopeMe:
		return scope.OwnerID
	default:
		return ""
	}
}

func configuredMemoryLoopOwnerID(ctx context.Context) (string, error) {
	ownerID, err := githubidentity.ResolveUsername(ctx)
	if err != nil {
		return "", fmt.Errorf("resolve GitHub username: %w", err)
	}
	return ownerID, nil
}

func renderEmptyMemoryLoopScopeMessage(ctx context.Context, w io.Writer, idb *insightsdb.InsightsDB, scope memoryLoopScope) error {
	if scope.Mode != memoryLoopScopeMe {
		fmt.Fprintf(w, "No sessions found for scope %s.\n", formatMemoryLoopScopeLabel(scope))
		return nil
	}

	hasOwnerIDData, err := idb.HasOwnerIDData(ctx)
	if err != nil {
		return fmt.Errorf("check owner ID coverage: %w", err)
	}
	if !hasOwnerIDData {
		fmt.Fprintf(
			w,
			"No personal sessions found for owner_id %q because the insights cache has no owner_id data yet.\n",
			scope.OwnerID,
		)
		fmt.Fprintln(w, "Commit a session under this GitHub account, then run `entire memory-loop refresh --scope me` again.")
		return nil
	}

	fmt.Fprintf(w, "No sessions found for personal scope %q.\n", scope.OwnerID)
	return nil
}

func newMemoryLoopEditCmd() *cobra.Command {
	var title, body, keywords string

	cmd := &cobra.Command{
		Use:   "edit <id>",
		Short: "Edit a memory's title, body, or keywords",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMemoryLoopEdit(cmd, args[0], title, body, keywords)
		},
	}
	cmd.Flags().StringVar(&title, "title", "", "New title")
	cmd.Flags().StringVar(&body, "body", "", "New body")
	cmd.Flags().StringVar(&keywords, "keywords", "", "Comma-separated keywords")
	return cmd
}

func runMemoryLoopEdit(cmd *cobra.Command, id, title, body, keywords string) error {
	ctx := cmd.Context()
	state, err := loadMemoryLoopStoreState(ctx)
	if err != nil {
		return err
	}

	var input memoryloop.EditRecordInput
	hasFlag := false
	if cmd.Flags().Changed("title") {
		input.Title = &title
		hasFlag = true
	}
	if cmd.Flags().Changed("body") {
		input.Body = &body
		hasFlag = true
	}
	if cmd.Flags().Changed("keywords") {
		kw := memoryloop.ParseKeywords(keywords)
		input.Keywords = &kw
		hasFlag = true
	}

	if !hasFlag {
		fmt.Fprintln(cmd.ErrOrStderr(), "Interactive edit mode not yet implemented. Use --title, --body, or --keywords flags.")
		return NewSilentError(errors.New("no flags provided"))
	}

	now := time.Now().UTC()
	records, record, err := memoryloop.EditRecord(state.Store.Records, id, input, now)
	if err != nil {
		return fmt.Errorf("edit memory: %w", err)
	}
	state.Store.Records = records
	if err := memoryloop.SaveState(ctx, state); err != nil {
		return fmt.Errorf("save memory-loop state: %w", err)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "Updated memory: %s\n", record.Title)
	return nil
}

func newMemoryLoopThresholdCmd() *cobra.Command {
	var clearOverrides bool
	var minStrength, evidenceSessions int
	var minConfidence, singletonPolicy string
	var genericFilter string

	cmd := &cobra.Command{
		Use:   "threshold [relaxed|balanced|strict]",
		Short: "Set generation threshold preset",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMemoryLoopThreshold(cmd, args, clearOverrides, minStrength, evidenceSessions, minConfidence, singletonPolicy, genericFilter)
		},
	}
	cmd.Flags().BoolVar(&clearOverrides, "clear-overrides", false, "Clear all threshold overrides")
	cmd.Flags().IntVar(&minStrength, "min-strength", 0, "Override minimum strength (1-5)")
	cmd.Flags().IntVar(&evidenceSessions, "evidence-sessions", 0, "Override required evidence sessions (1-10)")
	cmd.Flags().StringVar(&minConfidence, "min-confidence", "", "Override minimum confidence (low|medium|high)")
	cmd.Flags().StringVar(&singletonPolicy, "singleton-policy", "", "Override singleton policy (all|review-rules|none)")
	cmd.Flags().StringVar(&genericFilter, "generic-filter", "", "Override generic filter (true|false)")
	return cmd
}

func runMemoryLoopThreshold(cmd *cobra.Command, args []string, clearOverrides bool, minStrength, evidenceSessions int, minConfidence, singletonPolicy, genericFilter string) error {
	ctx := cmd.Context()
	s, err := settings.Load(ctx)
	if err != nil {
		return fmt.Errorf("load settings: %w", err)
	}
	if s.MemoryLoopConfig == nil {
		s.MemoryLoopConfig = &settings.MemoryLoopSettings{}
	}

	if len(args) > 0 {
		preset := args[0]
		switch preset {
		case "relaxed", "balanced", "strict":
			s.MemoryLoopConfig.GenerationThreshold = preset
		default:
			return fmt.Errorf("unknown threshold preset: %s (expected relaxed, balanced, or strict)", preset)
		}
	}

	if clearOverrides {
		s.MemoryLoopConfig.GenerationOverrides = nil
	} else {
		if cmd.Flags().Changed("min-strength") || cmd.Flags().Changed("evidence-sessions") ||
			cmd.Flags().Changed("min-confidence") || cmd.Flags().Changed("singleton-policy") ||
			cmd.Flags().Changed("generic-filter") {
			if s.MemoryLoopConfig.GenerationOverrides == nil {
				s.MemoryLoopConfig.GenerationOverrides = &settings.GenerationThresholdOverrides{}
			}
			ov := s.MemoryLoopConfig.GenerationOverrides
			if cmd.Flags().Changed("min-strength") {
				ov.MinStrength = &minStrength
			}
			if cmd.Flags().Changed("evidence-sessions") {
				ov.EvidenceSessions = &evidenceSessions
			}
			if cmd.Flags().Changed("min-confidence") {
				ov.MinConfidence = &minConfidence
			}
			if cmd.Flags().Changed("singleton-policy") {
				ov.SingletonPolicy = &singletonPolicy
			}
			if cmd.Flags().Changed("generic-filter") {
				val := genericFilter == "true"
				ov.GenericFilter = &val
			}
		}
	}

	if err := settings.Save(ctx, s); err != nil {
		return fmt.Errorf("save settings: %w", err)
	}

	preset := s.MemoryLoopConfig.GenerationThreshold
	if preset == "" {
		preset = "balanced"
	}
	fmt.Fprintf(cmd.OutOrStdout(), "Generation threshold set to: %s\n", preset)
	if s.MemoryLoopConfig.GenerationOverrides != nil {
		fmt.Fprintln(cmd.OutOrStdout(), "Overrides are active.")
	}
	return nil
}

