var validKindFocusValues = map[memoryloop.Kind]bool{
	memoryloop.KindRepoRule:         true,
	memoryloop.KindWorkflowRule:     true,
	memoryloop.KindAgentInstruction: true,
	memoryloop.KindSkillPatch:       true,
	memoryloop.KindAntiPattern:      true,
}

func runMemoryLoopRefresh(ctx context.Context, w io.Writer, last int, scopeArg, branchArg, kindArg string, debug bool) error {
	var kindFocus memoryloop.Kind
	if kindArg != "" {
		kindFocus = memoryloop.Kind(kindArg)
		if !validKindFocusValues[kindFocus] {
			return fmt.Errorf("invalid --kind value %q; must be one of: repo_rule, workflow_rule, agent_instruction, skill_patch, anti_pattern", kindArg)
		}
	}

	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("not in a git repository: %w", err)
	}

	cfg, cfgErr := LoadEntireSettings(ctx)
	if cfgErr != nil {
		return fmt.Errorf("load settings: %w", cfgErr)
	}

	idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
	if err != nil {
		return fmt.Errorf("open insights cache: %w", err)
	}
	defer func() { _ = idb.Close() }()

	renderMemoryLoopRefreshProgress(w, "Refreshing cache...")
	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // non-fatal

	scope, err := resolveMemoryLoopScope(ctx, scopeArg, branchArg)
	if err != nil {
		return err
	}

	state, err := loadMemoryLoopState(ctx)
	if err != nil {
		return fmt.Errorf("load memory-loop state: %w", err)
	}

	memoryCfg := cfg.GetMemoryLoopConfig()
	thresholdPreset := memoryCfg.GenerationThreshold
	if thresholdPreset == "" {
		thresholdPreset = "balanced"
	}
	var thresholdOverrides *memoryloop.GenerationThresholdOverrides
	if memoryCfg.GenerationOverrides != nil {
		thresholdOverrides = &memoryloop.GenerationThresholdOverrides{
			MinStrength:      memoryCfg.GenerationOverrides.MinStrength,
			MinConfidence:    memoryCfg.GenerationOverrides.MinConfidence,
			EvidenceSessions: memoryCfg.GenerationOverrides.EvidenceSessions,
			GenericFilter:    memoryCfg.GenerationOverrides.GenericFilter,
			SingletonPolicy:  memoryCfg.GenerationOverrides.SingletonPolicy,
		}
	}

	maxInjected := memoryCfg.MaxInjected
	mode := memoryloop.Mode(memoryCfg.Mode)
	storeDebug := memoryCfg.Debug
	activationPolicy := memoryloop.ActivationPolicy(memoryCfg.ActivationPolicy)
	var injectionScopes []memoryloop.ScopeKind
	if state.Store != nil {
		if state.Store.Mode != "" {
			mode = state.Store.Mode
		}
		storeDebug = state.Store.Debug
		if state.Store.MaxInjected > 0 {
			maxInjected = state.Store.MaxInjected
		}
		if state.Store.ActivationPolicy != "" {
			activationPolicy = state.Store.ActivationPolicy
		}
		if state.Store.GenerationThreshold != "" {
			thresholdPreset = state.Store.GenerationThreshold
		}
		if state.Store.GenerationOverrides != nil {
			thresholdOverrides = state.Store.GenerationOverrides
		}
		if len(state.Store.InjectionScopes) > 0 {
			injectionScopes = state.Store.InjectionScopes
		}
	}

	thresholdCfg := memoryloop.ResolveGenerationThreshold(thresholdPreset, thresholdOverrides)

	switch scope.Mode {
	case memoryLoopScopeRepo, memoryLoopScopeBranch:
		renderMemoryLoopRefreshProgress(w, fmt.Sprintf("Scope: %s (branch: %s)", scope.Mode, scope.Branch))
	case memoryLoopScopeMe:
		renderMemoryLoopRefreshProgress(w, fmt.Sprintf("Scope: me (%s)", scope.OwnerID))
	}
	thresholdLabel := thresholdPreset
	if thresholdOverrides != nil {
		thresholdLabel += " (with overrides)"
	}
	renderMemoryLoopRefreshProgress(w, "Generation threshold: "+thresholdLabel)
	if kindFocus != "" {
		renderMemoryLoopRefreshProgress(w, "Generation kind: "+string(kindFocus))
	}

	renderMemoryLoopRefreshProgress(w, "Loading scoped sessions...")
	rows, err := queryMemoryLoopRows(ctx, idb, scope, last)
	if err != nil {
		return fmt.Errorf("query sessions: %w", err)
	}

	if settings.IsSummarizeEnabled(ctx) && len(rows) > 0 {
		renderMemoryLoopRefreshProgress(w, "Backfilling summaries for scoped sessions...")
		backfillSessionRows(ctx, w, idb, rows, debug)
	}

	// Re-query to pick up backfilled data.
	rows, err = queryMemoryLoopRows(ctx, idb, scope, last)
	if err != nil {
		return fmt.Errorf("query sessions: %w", err)
	}
	if len(rows) == 0 {
		if err := renderEmptyMemoryLoopScopeMessage(ctx, w, idb, scope); err != nil {
			return err
		}
		return nil
	}

	analysis := improve.AnalyzePatterns(sessionRowsToSummaries(rows))

	gen := memoryloop.Generator{Runner: &llmcli.Runner{}}
	renderMemoryLoopRefreshProgress(w, "Distilling memories...")
	records, generationStats, usage, err := gen.Generate(ctx, memoryloop.GenerateInput{
		Analysis:        analysis,
		Sessions:        rows,
		SourceWindow:    last,
		MaxRecords:      memoryloop.DefaultMaxRecords,
		ThresholdConfig: thresholdCfg,
		KindFocus:       kindFocus,
	})
	if err != nil {
		return fmt.Errorf("generate memory snapshot: %w", err)
	}

	now := time.Now().UTC()
	scopeValue := scopeValue(scope)
	renderMemoryLoopRefreshProgress(w, "Reconciling with existing memory history...")
	reconcile := memoryloop.ReconcileGeneratedRecords(
		existingMemoryRecords(state),
		records,
		scopeKindForRefresh(scope),
		scopeValue,
		activationPolicy,
		now,
	)
	reconcile.History.Scope = string(scope.Mode)
	reconcile.History.SourceWindow = last
	reconcile.History.FilteredWeakCount = generationStats.FilteredWeakCount
	reconcile.History.FilteredGenericCount = generationStats.FilteredGenericCount
	reconcile.History.FilteredNoEvidenceCount = generationStats.FilteredNoEvidenceCount
	reconcile.History.DedupedCount = generationStats.DedupedCount
	reconcile.History.Threshold = thresholdPreset
	reconcile.History.ThresholdOverride = thresholdOverrides != nil
	reconcile.History.ResolvedConfig = &thresholdCfg
	refreshHistory := append(existingRefreshHistory(state), reconcile.History)
	reconciledRecords := memoryloop.DeriveOutcomes(reconcile.Records, rows, now)
	reconciledRecords, pruneResult := memoryloop.PruneRecords(reconciledRecords, now)
	if len(refreshHistory) > 0 {
		lastIdx := len(refreshHistory) - 1
		refreshHistory[lastIdx].DemotedCount = pruneResult.DemotedCount
		refreshHistory[lastIdx].PrunedCount = pruneResult.PrunedCount
		if usage != nil {
			refreshHistory[lastIdx].InputTokens = usage.InputTokens
			refreshHistory[lastIdx].OutputTokens = usage.OutputTokens
			refreshHistory[lastIdx].TotalCostUSD = usage.TotalCostUSD
		}
	}

	state.Store = &memoryloop.Store{
		Version:             1,
		GeneratedAt:         now,
		SourceWindow:        last,
		Scope:               string(scope.Mode),
		ScopeValue:          scopeValue,
		Records:             reconciledRecords,
		Mode:                mode,
		Debug:               storeDebug,
		ActivationPolicy:    activationPolicy,
		MaxInjected:         maxInjected,
		InjectionScopes:     injectionScopes,
		GenerationThreshold: thresholdPreset,
		GenerationOverrides: thresholdOverrides,
		RefreshHistory:      refreshHistory,
	}

	renderMemoryLoopRefreshProgress(w, "Saving memory store...")
	if err := memoryloop.SaveState(ctx, state); err != nil {
		return fmt.Errorf("save memory-loop state: %w", err)
	}

	activeCount, candidateCount, suppressedCount, archivedCount := countMemoryStatuses(reconciledRecords)
	generatedTitles := make([]string, 0, len(records))
	for _, record := range records {
		if title := strings.TrimSpace(record.Title); title != "" {
			generatedTitles = append(generatedTitles, title)
		}
	}
	renderMemoryLoopRefreshSummary(w, memoryLoopRefreshSummary{
		SessionCount:         len(rows),
		ScopeLabel:           formatMemoryLoopScopeLabel(scope),
		GeneratedCount:       reconcile.History.GeneratedCount,
		ActivatedCount:       reconcile.History.ActivatedCount,
		CandidateCount:       reconcile.History.CandidateCount,
		ActiveCount:          activeCount,
		StoredCandidateCount: candidateCount,
		SuppressedCount:      suppressedCount,
		ArchivedCount:        archivedCount,
		GeneratedTitles:      generatedTitles,
	})
	if usage != nil {
		renderUsageLine(w, usage)
	}

	return nil
}

func existingMemoryRecords(state *memoryloop.State) []memoryloop.MemoryRecord {
	if state == nil || state.Store == nil {
		return nil
	}
	return state.Store.Records
}

func existingRefreshHistory(state *memoryloop.State) []memoryloop.RefreshHistory {
	if state == nil || state.Store == nil {
		return nil
	}
	return append([]memoryloop.RefreshHistory(nil), state.Store.RefreshHistory...)
}

func backfillSessionRows(ctx context.Context, w io.Writer, idb *insightsdb.InsightsDB, rows []insightsdb.SessionRow, debug bool) {
	hint := "use --debug for skipped details"
	backfillSummariesForRows(ctx, w, idb, rows, debug, hint)
	backfillFacetsForRows(ctx, w, idb, rows, debug, hint)
}

func renderMemoryLoopRefreshProgress(w io.Writer, line string) {
	fmt.Fprintln(w, strings.TrimSpace(line))
}

func renderMemoryLoopRefreshSummary(w io.Writer, summary memoryLoopRefreshSummary) {
	fmt.Fprintf(w, "Memory Loop refreshed from %d sessions\n", summary.SessionCount)
	if summary.ScopeLabel != "" {
		fmt.Fprintf(w, "Scope: %s\n", summary.ScopeLabel)
	}
	fmt.Fprintf(
		w,
		"This refresh: generated %d, activated %d, candidate %d\n",
		summary.GeneratedCount,
		summary.ActivatedCount,
		summary.CandidateCount,
	)
	fmt.Fprintf(
		w,
		"Stored memories: active %d, candidate %d, suppressed %d, archived %d\n",
		summary.ActiveCount,
		storedCandidateCount(summary),
		summary.SuppressedCount,
		summary.ArchivedCount,
	)
	for _, title := range summary.GeneratedTitles {
		fmt.Fprintf(w, "  - %s\n", title)
	}
}

func formatMemoryLoopScopeLabel(scope memoryLoopScope) string {
	label := string(scope.Mode)
	if value := strings.TrimSpace(scopeValue(scope)); value != "" {
		label = fmt.Sprintf("%s (%s)", label, value)
	}
	return label
}

func storedCandidateCount(summary memoryLoopRefreshSummary) int {
	if summary.StoredCandidateCount > 0 {
		return summary.StoredCandidateCount
	}
	return summary.CandidateCount
}

func scopeKindForRefresh(scope memoryLoopScope) memoryloop.ScopeKind {
	switch scope.Mode {
	case memoryLoopScopeMe:
		return memoryloop.ScopeKindMe
	case memoryLoopScopeBranch:
		return memoryloop.ScopeKindBranch
	case memoryLoopScopeRepo:
		return memoryloop.ScopeKindRepo
	default:
		return memoryloop.ScopeKindRepo
	}
}

func runMemoryLoopShow(ctx context.Context, w io.Writer, _ string) error {
	state, err := loadMemoryLoopState(ctx)
	if err != nil {
		return fmt.Errorf("load memory-loop state: %w", err)
	}

	s := termstyle.New(w)
	fmt.Fprintln(w, s.Render(s.Bold, "Entire Memory Loop"))

	if state.Snapshot == nil {
		fmt.Fprintln(w, "No memory snapshot found. Run `entire memory-loop refresh` first.")
		return nil
	}

	snapshot := state.Snapshot
	activeCount, candidateCount, suppressedCount, archivedCount := countMemoryStatuses(snapshot.Records)
	if !snapshot.GeneratedAt.IsZero() {
		fmt.Fprintf(w, "Last refresh: %s\n", snapshot.GeneratedAt.Format(time.RFC3339))
	}
	if snapshot.Scope != "" {
		fmt.Fprintf(w, "Scope: %s", snapshot.Scope)
		if snapshot.ScopeValue != "" {
			fmt.Fprintf(w, " (%s)", snapshot.ScopeValue)
		}
		fmt.Fprintln(w)
	}
	fmt.Fprintf(w, "Active memories: %d\n", activeCount)
	fmt.Fprintf(w, "Candidate memories: %d\n", candidateCount)
	fmt.Fprintf(w, "Suppressed memories: %d\n", suppressedCount)
	fmt.Fprintf(w, "Archived memories: %d\n", archivedCount)
	fmt.Fprintf(w, "Mode: %s\n", displayMemoryMode(snapshot.Mode))
	fmt.Fprintf(w, "Debug: %s\n", displayToggle(snapshot.Debug))
	fmt.Fprintf(w, "Activation policy: %s\n", displayActivationPolicy(snapshot.ActivationPolicy))
	fmt.Fprintf(w, "Max injected: %d\n\n", snapshot.MaxInjected)
	renderDetailedMemorySections(w, s, snapshot.Records)
	renderRefreshHistorySection(w, s, snapshot.RefreshHistory)
	renderRecentInjectionsSection(w, s, state.InjectionLogs)

	frequent := frequentMemoryTitles(snapshot, state.InjectionLogs)
	if len(frequent) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, s.SectionRule("Most Injected"))
		for _, item := range frequent[:min(5, len(frequent))] {
			fmt.Fprintf(w, "  - %s\n", item)
		}
	}

	return nil
}

func runMemoryLoopStatus(ctx context.Context, w io.Writer, prompt string, verbose bool) error {
	state, err := loadMemoryLoopState(ctx)
	if err != nil {
		return fmt.Errorf("load memory-loop state: %w", err)
	}

	s := termstyle.New(w)
	fmt.Fprintln(w, s.Render(s.Bold, "Entire Memory Loop"))

	if state.Snapshot == nil {
		fmt.Fprintln(w, "No memory snapshot found. Run `entire memory-loop refresh` first.")
		return nil
	}

	snapshot := state.Snapshot
	activeCount, candidateCount, suppressedCount, archivedCount := countMemoryStatuses(snapshot.Records)
	if !snapshot.GeneratedAt.IsZero() {
		fmt.Fprintf(w, "Last refresh: %s\n", snapshot.GeneratedAt.Format(time.RFC3339))
	}
	if snapshot.Scope != "" {
		fmt.Fprintf(w, "Scope: %s", snapshot.Scope)
		if snapshot.ScopeValue != "" {
			fmt.Fprintf(w, " (%s)", snapshot.ScopeValue)
		}
		fmt.Fprintln(w)
	}
	fmt.Fprintf(w, "Mode: %s\n", displayMemoryMode(snapshot.Mode))
	fmt.Fprintf(w, "Debug: %s\n", displayToggle(snapshot.Debug))
	fmt.Fprintf(w, "Activation policy: %s\n", displayActivationPolicy(snapshot.ActivationPolicy))
	fmt.Fprintf(w, "Max injected: %d\n", snapshot.MaxInjected)
	fmt.Fprintf(w, "Active memories: %d\n", activeCount)
	fmt.Fprintf(w, "Candidate memories: %d\n", candidateCount)
	fmt.Fprintf(w, "Suppressed memories: %d\n", suppressedCount)
	fmt.Fprintf(w, "Archived memories: %d\n", archivedCount)

	if prompt != "" {
		fmt.Fprintln(w)
		fmt.Fprintln(w, s.SectionRule("Prompt Preview"))
		report := memoryloop.PreviewSelection(*snapshot, prompt, time.Now().UTC(), buildMemoryLoopSelectOpts(ctx, snapshot)...)
		if len(report.Matches) == 0 {
			fmt.Fprintln(w, "  No memories would inject for that prompt.")
		} else {
			fmt.Fprintln(w, indentBlock(memoryloop.FormatInjectionBlock(report.Matches), "  "))
			if verbose {
				for _, match := range report.Matches {
					fmt.Fprintf(
						w,
						"  - %s [%s] score=%d base_score=%d adjusted_score=%d cooldown_penalty=%d outcome_bonus=%d scope_bonus=%d reason=%s scope=%s status=%s\n",
						match.Record.ID,
						match.Record.Kind,
						match.Score,
						match.Rationale.BaseScore,
						match.Rationale.AdjustedScore,
						match.Rationale.CooldownPenalty,
						match.Rationale.OutcomeBonus,
						match.Rationale.ScopeBonus,
						match.Reason,
						formatMemoryLoopRecordScope(match.Record),
						displayMemoryStatus(match.Record.Status),
					)
				}
				for _, skipped := range report.Skipped {
					if skipped.Record.ID == "" {
						fmt.Fprintf(w, "  - %s\n", skipped.Reason)
						continue
					}
					fmt.Fprintf(
						w,
						"  - %s [%s] %s scope=%s status=%s\n",
						skipped.Record.ID,
						skipped.Record.Kind,
						skipped.Reason,
						formatMemoryLoopRecordScope(skipped.Record),
						displayMemoryStatus(skipped.Record.Status),
					)
				}
			}
		}
	}

	return nil
}

